using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ApplyBatch02 {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/VARCO_V002_Batch02_20261103"));
static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;
static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
static Bounds B(GameObject g){var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var x in rr.Skip(1))b.Encapsulate(x.bounds);return b;}
static object C(Collider c)=>new {path=P(c.transform),type=c.GetType().Name,position=V(c.transform.position),rotation=V(c.transform.eulerAngles),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,boundsCenter=V(c.bounds.center),boundsSize=V(c.bounds.size)};
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var original=SceneManager.GetActiveScene().path;var cfg=JArray.Parse(File.ReadAllText(Path.Combine(R,"unity_prepared_manifest.json")));var plan=JArray.Parse(File.ReadAllText(Path.Combine(R,"placements.json")));var before=JArray.Parse(File.ReadAllText(Path.Combine(R,"unity_inventory_before.json")));var results=new List<object>();
foreach(JObject baseline in before){string path=(string)baseline["scene"];var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var records=new List<object>();
foreach(JObject p in plan){var room=all.FirstOrDefault(t=>t!=null&&P(t)==(string)p["room"]);if(room==null)continue;string id=(string)p["id"];var a=cfg.First(x=>(string)x["id"]==id);var group=room.Find("VARCO_Batch02_Visuals");if(group==null){var gg=new GameObject("VARCO_Batch02_Visuals");gg.transform.SetParent(room,false);group=gg.transform;}string name=id+"_"+(string)a["name"]+"_"+plan.IndexOf(p);if(group.Find(name)!=null){UnityEngine.Object.DestroyImmediate(group.Find(name).gameObject);}var prefab=AssetDatabase.LoadAssetAtPath<GameObject>((string)a["prefabPath"]);if(prefab==null)throw new Exception("Missing prefab "+id);var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,s);g.name=name;g.transform.SetParent(group,false);g.transform.localPosition=new Vector3((float)p["pos"][0],(float)p["pos"][1],(float)p["pos"][2]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);foreach(var t in g.GetComponentsInChildren<Transform>())GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.BatchingStatic|StaticEditorFlags.ReflectionProbeStatic);Physics.SyncTransforms();var b=B(g);var overlaps=Physics.OverlapBox(b.center,b.extents*.97f,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Select(c=>P(c.transform)).ToArray();records.Add(new{id=id,name=name,room=(string)p["room"],overlaps=overlaps,center=V(b.center),size=V(b.size)});}
all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();bool same=JToken.DeepEquals(baseline["colliders"],JToken.Parse(JsonConvert.SerializeObject(all.SelectMany(t=>t.GetComponents<Collider>()).Select(C).ToArray())));if(!same)throw new Exception("Collider changed "+path);if(all.Any(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0))throw new Exception("Missing script");EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);results.Add(new{scene=path,collidersPreserved=same,placements=records});}
File.WriteAllText(Path.Combine(R,"unity_placement_facts.json"),JsonConvert.SerializeObject(results,Formatting.Indented));EditorSceneManager.OpenScene(original,OpenSceneMode.Single);return "Batch02 applied; review overlap report";}}

